private theorem summable_tail {t : ℝ} (ht : 1 < t) {n : ℕ} (hn : 1 ≤ n) :
    Summable (fun k : ℕ =>
      ((t⁻¹) ^ k) ^ (n + 1) * latVal t n k / ((t : ℝ) ^ n - (t⁻¹) ^ k))

private theorem legVal_sub_latVal' {t : ℝ} (ht : 1 < t) (n k : ℕ) :
    legVal t n - latVal t n k
      = ∑ j ∈ Finset.range (n + 1), legGamma t n j * (((t : ℝ) ^ n) ^ j - ((t⁻¹) ^ k) ^ j)

private theorem summable_cross {t : ℝ} (ht : 1 < t) (n : ℕ) :
    Summable (fun k : ℕ => ∑ j ∈ Finset.range (n + 1), ∑ i ∈ Finset.range j,
      legGamma t n j * ((t : ℝ) ^ n) ^ i * (((t⁻¹) ^ k) ^ (j - i) * latVal t n k))

private theorem tsum_cross_zero {t : ℝ} (ht : 1 < t) {n : ℕ} (_hn : 1 ≤ n) :
    (∑' k : ℕ, ∑ j ∈ Finset.range (n + 1), ∑ i ∈ Finset.range j,
      legGamma t n j * ((t : ℝ) ^ n) ^ i * (((t⁻¹) ^ k) ^ (j - i) * latVal t n k)) = 0

private theorem rem_eq_tail {t : ℝ} (ht : 1 < t) {n : ℕ} (hn : 1 ≤ n) :
    rem t n = ((t : ℝ) ^ (n * n))⁻¹ *
      ∑' k : ℕ, ((t⁻¹) ^ k) ^ (n + 1) * latVal t n k / ((t : ℝ) ^ n - (t⁻¹) ^ k)

private theorem abs_rem_le {t : ℝ} (ht : 1 < t) {n : ℕ} (hn : 1 ≤ n) :
    |rem t n| ≤ ((t : ℝ) ^ (n * n))⁻¹ *
      (((t : ℝ) ^ n - 1)⁻¹ * ∑' k : ℕ, (t⁻¹) ^ k * |latVal t n k|)

private theorem summable_master {t : ℝ} (ht : 1 < t) (n : ℕ) {g : ℕ → ℝ} {M : ℝ}
    (hg : ∀ k, |g k| ≤ M) :
    Summable (fun k : ℕ => t⁻¹ ^ k * g k / (t ^ n - t⁻¹ ^ k))

private theorem legVal_sub_latVal {t : ℝ} (ht : 1 < t) (n k : ℕ) :
    legVal t n - latVal t n k
      = ∑ j ∈ Finset.range (n + 1), legGamma t n j * ((t ^ n) ^ j - (t⁻¹ ^ k) ^ j)

private theorem gauss_le_const_mul_pow_aux {t : ℝ} (ht : 1 < t) (m k : ℕ) :
    (∏ j ∈ Finset.range k, (t ^ (m + j + 1) - 1) / (t ^ (j + 1) - 1))
      ≤ gaussConst t * t ^ (k * m)

private theorem gauss_prod {t : ℝ} (ht : 1 < t) {n j : ℕ} (hj : j ≤ n) :
    gauss t n j * gauss t (n + j) n * (Rfac t j * Rfac t j * Rfac t (n - j))
      = Rfac t (n + j)

private theorem Nprod_eval {t : ℝ} (ht : 1 < t) (n j : ℕ) :
    Rfac t j * (t ^ (n * j) * ∏ r ∈ Finset.range n, ((t⁻¹) ^ j - t ^ (r + 1)))
      = (-1) ^ n * Rfac t (n + j)

private theorem lattice_term (t : ℝ) (n p k : ℕ) :
    ((t⁻¹) ^ k) ^ (p + 1) * legG t n ((t⁻¹) ^ k * (t ^ n)⁻¹)
      = ∑ j ∈ Finset.range (n + 1), legGamma t n j * ((t⁻¹) ^ (p + j + 1)) ^ k

private theorem nodal_num {t : ℝ} (n : ℕ) :
    (∏ r ∈ Finset.range n, (t ^ (n + 1) - t ^ (r + 1)))
      = t ^ ((n + 1).choose 2) * Rfac t n

private theorem legGamma_diag {t : ℝ} (ht : 1 < t) (n : ℕ) :
    ((-1 : ℝ)) ^ n * legGamma t n n
      = t ^ (n.choose 2) * Rfac t (2 * n) / (t ^ (n * n) * (Rfac t n * Rfac t n))

private theorem qterm_rw {t : ℝ} (ht : 1 < t) {n i j : ℕ} (hij : i < j) (hjn : j ≤ n) :
    legGamma t n j * ((t ^ n) ^ i * (t ^ (j - i) / (t ^ (j - i) - 1)))
      = legCoef t n j * ((t ^ ((n - 1) * (j - i)))⁻¹ * (t ^ (j - i) - 1)⁻¹)

theorem half_pow_le_signed_legVal {t : ℝ} (ht : 2 ≤ t) {n : ℕ}
    (hn : 4 * gaussConst t ^ 2 ≤ t ^ n) :
    t ^ degTerm n n / 2 ≤ (-1) ^ n * legVal t n

theorem Dsharp_div_mem_Zr {P Q : ℤ} (hQ : 0 < Q) (hPQ : Q < P) {n ℓ : ℕ}
    (hℓ : 1 ≤ ℓ) (hn : ℓ ≤ n) :
    (Dsharp P Q n : ℝ) * (1 / (((P : ℝ) / (Q : ℝ)) ^ ℓ - 1)) ∈ Zr

theorem Dsharp_mul_mem_Zr {P Q : ℤ} (hQ : 0 < Q) (hPQ : Q < P) {n ℓ : ℕ}
    (hℓ : 1 ≤ ℓ) (hn : ℓ ≤ n) :
    (Dsharp P Q n : ℝ) * ((((P : ℝ) / (Q : ℝ)) ^ ℓ) / ((((P : ℝ) / (Q : ℝ)) ^ ℓ) - 1)) ∈ Zr

theorem sum_abs_latVal_le {t : ℝ} (ht : 1 < t) (n : ℕ) {h : ℝ}
    (hh : ∑' k : ℕ, (t⁻¹) ^ k * (latVal t n k) ^ 2 ≤ h) :
    ∑' k : ℕ, (t⁻¹) ^ k * |latVal t n k| ≤ Real.sqrt ((1 - t⁻¹)⁻¹) * Real.sqrt h

private theorem block_one_mem_Zr {P Q : ℤ} (hQ : 0 < Q) (hPQ : Q < P) (n : ℕ) :
    (Q : ℝ) ^ Cexp n *
        (∑ j ∈ Finset.range (n + 1), (j : ℝ) * legCoef ((P : ℝ) / (Q : ℝ)) n j) ∈ Zr

private theorem sum_reflect_trunc (n s : ℕ) (f : ℕ → ℝ) (hsn : s < n)
    (hvan : ∀ b, s < b → b ≤ n → f (n - b) = 0) :
    ∑ a ∈ Finset.range (n + 1), f a = ∑ b ∈ Finset.range (s + 1), f (n - b)
